import{_ as t,o as n,c as a,a3 as r}from"./chunks/framework.CoXsll4d.js";const p=JSON.parse('{"title":"Séance 1 — Comprendre la machine et bien formuler sa demande","description":"","frontmatter":{},"headers":[],"relativePath":"seances/01-comprendre-la-machine.md","filePath":"seances/01-comprendre-la-machine.md"}'),o={name:"seances/01-comprendre-la-machine.md"};function s(i,e,l,d,u,c){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="seance-1-—-comprendre-la-machine-et-bien-formuler-sa-demande" tabindex="-1">Séance 1 — Comprendre la machine et bien formuler sa demande <a class="header-anchor" href="#seance-1-—-comprendre-la-machine-et-bien-formuler-sa-demande" aria-label="Permalink to &quot;Séance 1 — Comprendre la machine et bien formuler sa demande&quot;">​</a></h1><p><strong>Lundi 30 novembre · 3 heures</strong></p><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><p>À la fin de la séance, vous pouvez :</p><ul><li>expliquer ce qu&#39;est un <strong>token</strong>, une <strong>fenêtre de contexte</strong>, et pourquoi un modèle peut répondre avec assurance quelque chose de faux ;</li><li>distinguer un <strong>chat</strong> d&#39;un <strong>agent</strong> (un modèle, des outils et une boucle) ;</li><li>rédiger une demande qui donne l&#39;<strong>objectif</strong>, le <strong>contexte</strong>, les <strong>contraintes</strong> et les <strong>critères de réussite</strong> ;</li><li>utiliser <strong>Git</strong> comme filet de sécurité quand un agent modifie votre code.</li></ul><h2 id="avant-la-seance" tabindex="-1">Avant la séance <a class="header-anchor" href="#avant-la-seance" aria-label="Permalink to &quot;Avant la séance&quot;">​</a></h2><ul><li>Votre demande <strong>GitHub Education</strong> est approuvée et <strong>Copilot</strong> est activé sur votre compte.</li><li><strong>Visual Studio 2026</strong> et le <strong>SDK .NET 10</strong> sont installés (<code>dotnet --list-sdks</code>).</li><li>Vous avez lu la mise en situation dans le README de <a href="https://github.com/Cochenille/Jumelo" target="_blank" rel="noreferrer">Jumelo</a>.</li></ul><h2 id="deroulement" tabindex="-1">Déroulement <a class="header-anchor" href="#deroulement" aria-label="Permalink to &quot;Déroulement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Durée</th><th>Activité</th></tr></thead><tbody><tr><td>40 min</td><td><strong>Diagnostic</strong> : créer votre dépôt à partir du template Jumelo, puis régler un problème signalé par la cliente, <strong>comme vous le faites d&#39;habitude</strong>. Gardez toutes vos requêtes.</td></tr><tr><td>40 min</td><td>Ce qu&#39;il y a dans la boîte : tokens, fenêtre de contexte, hallucinations, choix du modèle et requêtes premium, chat ou agent.</td></tr><tr><td>10 min</td><td>Pause</td></tr><tr><td>30 min</td><td>Anatomie d&#39;une bonne demande, analysée à partir de <strong>vos propres requêtes</strong> du diagnostic.</td></tr><tr><td>50 min</td><td><strong>Activité</strong> : Copilot en mode Agent sur Jumelo.</td></tr><tr><td>10 min</td><td>Bilan</td></tr></tbody></table><h2 id="activite" tabindex="-1">Activité <a class="header-anchor" href="#activite" aria-label="Permalink to &quot;Activité&quot;">​</a></h2><ol><li>Demandez à l&#39;agent d&#39;<strong>expliquer</strong> l&#39;architecture de Jumelo avant de lui faire modifier quoi que ce soit.</li><li>Lancez <code>dotnet test</code>. Un test échoue : avec l&#39;agent, trouvez pourquoi et corrigez <strong>le code</strong>, pas le test.</li><li>Relisez le diff avant de l&#39;accepter, puis faites un commit.</li><li>Revenez au problème du diagnostic avec ce que vous avez appris. Qu&#39;est-ce qui change dans vos requêtes ?</li></ol><div class="warning custom-block"><p class="custom-block-title">Ne jamais affaiblir un test</p><p>Un agent à qui l&#39;on demande « fais passer le test » peut modifier le test au lieu du code. Vous restez responsable du code que vous acceptez.</p></div><h2 id="notions-a-retenir" tabindex="-1">Notions à retenir <a class="header-anchor" href="#notions-a-retenir" aria-label="Permalink to &quot;Notions à retenir&quot;">​</a></h2><ul><li>Un modèle prédit la suite d&#39;un texte, token par token ; ses réponses ne sont pas déterministes.</li><li>Tout ce que le modèle « sait » de votre projet est dans sa fenêtre de contexte. Ce qui n&#39;y est pas, il le devine.</li><li>Une bonne demande dit <strong>quoi</strong>, <strong>pourquoi</strong>, <strong>avec quelles contraintes</strong> et <strong>comment savoir que c&#39;est réussi</strong>.</li><li>Petits commits fréquents : on peut toujours revenir en arrière.</li></ul>',14)])])}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
